class Node:
    def __init__(self, val, next=None):
        self.val = val
        self.next = next


def to_text(head):
    parts = []
    node = head
    while node:
        parts.append(str(node.val))
        node = node.next
    return " -> ".join(parts)


def push_front(head, val):
    return Node(val, head)


def push_back(head, val):
    if head is None:
        return Node(val)
    tail = head
    while tail.next:
        tail = tail.next
    tail.next = Node(val)
    return head


def delete_first(head, target):
    dummy = Node(0, head)
    prev = dummy
    while prev.next:
        if prev.next.val == target:
            prev.next = prev.next.next
            break
        prev = prev.next
    return dummy.next


head = Node(2, Node(3))
head = push_front(head, 1)
print(to_text(head))
head = push_back(head, 4)
print(to_text(head))
head = delete_first(head, 1)
print(to_text(head))
head = delete_first(head, 3)
print(to_text(head))

