    while node:
        parts.append(str(node.val))
        node = node.next
    return " -> ".join(parts)


def reverse(head):
    prev = None
    curr = head
    while curr:
        nxt = curr.next  # save the rest before the link changes
        curr.next = prev
        prev = curr
        curr = nxt
    return prev


head = build([1, 2, 3, 4])
old_head = head
head = reverse(head)
print(to_text(head))
print(f"Old head: {old_head.val}, next: {old_head.next}")

