class Node:
    def __init__(self, val, next=None):
        self.val = val
        self.next = next


def build(values):
    head = None
    for val in reversed(values):
        head = Node(val, head)
    return head


def middle_value(head):
    slow = fast = head
    while fast and fast.next:
        slow = slow.next
        fast = fast.next.next
    return slow.val


def has_cycle(head):
    slow = fast = head
    while fast and fast.next:
        slow = slow.next
        fast = fast.next.next
        if slow is fast:
            return True
    return False


values = list(map(int, input().split()))
pos = int(input())
head = build(values)
print(f"Middle: {middle_value(head)}")

if pos != -1:
    tail = head
    while tail.next:
        tail = tail.next
    target = head
    for _ in range(pos):
        target = target.next
    tail.next = target

print(f"Cycle: {has_cycle(head)}")
